namespace UniversityCourseCatalog.Data;

public record Department(int Id, string Name, string Code, string Description);

public record Course(
    int Id,
    string Code,
    string Title,
    string Description,
    int Credits,
    string Schedule,
    string InstructorName,
    string InstructorBio,
    int DepartmentId,
    bool IsFeatured);

public record EnrollmentRequest(
    string StudentName,
    string StudentId,
    int CourseId);

public static class CatalogData
{
    public static List<Department> Departments { get; } = new()
    {
        new(1, "Computer Science", "CS", "Study of computation, algorithms, and information systems."),
        new(2, "Mathematics", "MATH", "Pure and applied mathematics, statistics, and data analysis."),
        new(3, "Physics", "PHYS", "Study of matter, energy, and the fundamental forces of nature."),
        new(4, "English", "ENG", "Literature, writing, and linguistic studies."),
        new(5, "History", "HIST", "Study of past events and their impact on civilization.")
    };

    public static List<Course> Courses { get; } = new()
    {
        new(1, "CS 101", "Introduction to Programming", "Learn the fundamentals of programming using C#. Topics include variables, control flow, functions, and object-oriented design.", 3, "MWF 9:00–9:50 AM", "Dr. Sarah Chen", "Dr. Chen has 15 years of experience in software engineering and has published extensively on programming pedagogy.", 1, true),
        new(2, "CS 201", "Data Structures & Algorithms", "Study of fundamental data structures (arrays, trees, graphs) and algorithm design techniques.", 4, "TTh 10:30–11:45 AM", "Dr. James Liu", "Dr. Liu specializes in algorithm optimization and competitive programming. Previously at Google Research.", 1, true),
        new(3, "CS 310", "Database Systems", "Relational database design, SQL, normalization, and transaction management.", 3, "MWF 1:00–1:50 PM", "Prof. Maria Garcia", "Prof. Garcia has worked on distributed database systems at major tech companies for over a decade.", 1, false),
        new(4, "CS 450", "Machine Learning", "Supervised and unsupervised learning, neural networks, and practical applications.", 4, "TTh 2:00–3:15 PM", "Dr. Alex Thompson", "Dr. Thompson leads the university AI lab and has published 50+ papers on deep learning.", 1, true),
        new(5, "MATH 101", "Calculus I", "Limits, derivatives, and integrals of single-variable functions.", 4, "MWF 8:00–8:50 AM", "Dr. Robert Kim", "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students.", 2, true),
        new(6, "MATH 201", "Linear Algebra", "Vector spaces, matrices, eigenvalues, and linear transformations.", 3, "TTh 9:00–10:15 AM", "Dr. Emily Watson", "Dr. Watson's research focuses on computational linear algebra and its applications in data science.", 2, false),
        new(7, "MATH 301", "Probability & Statistics", "Probability theory, random variables, hypothesis testing, and regression.", 3, "MWF 11:00–11:50 AM", "Prof. David Park", "Prof. Park consults for biotech firms on statistical modeling and clinical trial design.", 2, false),
        new(8, "PHYS 101", "General Physics I", "Mechanics, thermodynamics, and waves. Calculus-based introductory physics.", 4, "MWF 10:00–10:50 AM", "Dr. Anna Petrova", "Dr. Petrova is a former CERN researcher specializing in particle physics education.", 3, true),
        new(9, "PHYS 220", "Electromagnetism", "Electric and magnetic fields, Maxwell's equations, and electromagnetic waves.", 4, "TTh 1:00–2:15 PM", "Dr. Michael Brown", "Dr. Brown has 20 years of teaching experience and authored a widely-used electromagnetism textbook.", 3, false),
        new(10, "ENG 101", "Composition & Rhetoric", "Develop clear, persuasive writing skills through essays and research papers.", 3, "MWF 9:00–9:50 AM", "Prof. Lisa Johnson", "Prof. Johnson is a published author and writing coach with expertise in academic and creative writing.", 4, false),
        new(11, "ENG 250", "American Literature", "Survey of American literature from the colonial period to the present.", 3, "TTh 11:00–12:15 PM", "Dr. William Davis", "Dr. Davis specializes in 20th-century American fiction and has written biographies of major American novelists.", 4, true),
        new(12, "HIST 101", "World Civilization I", "Survey of world history from ancient civilizations through the Renaissance.", 3, "MWF 2:00–2:50 PM", "Dr. Karen Martinez", "Dr. Martinez is an archaeologist and historian with fieldwork experience across three continents.", 5, false),
        new(13, "HIST 215", "Modern European History", "Europe from the Enlightenment through the 20th century, including wars, revolutions, and cultural movements.", 3, "TTh 3:30–4:45 PM", "Prof. Richard Taylor", "Prof. Taylor has authored several books on European political history and serves as a historical consultant.", 5, true),
    };

    public static Department? GetDepartment(int id) => Departments.FirstOrDefault(d => d.Id == id);
    public static Course? GetCourse(int id) => Courses.FirstOrDefault(c => c.Id == id);
    public static IEnumerable<Course> GetCoursesByDepartment(int departmentId) => Courses.Where(c => c.DepartmentId == departmentId);
    public static IEnumerable<Course> GetFeaturedCourses() => Courses.Where(c => c.IsFeatured);
}

@page "/courses"
@using UniversityCourseCatalog.Data

<PageTitle>Courses — University Course Catalog</PageTitle>

<h1>Course Catalog</h1>

<form method="get" action="/courses" class="row g-3 mb-4">
    <div class="col-md-5">
        <input type="text" name="search" value="@Search" class="form-control" placeholder="Search by title or code..." />
    </div>
    <div class="col-md-4">
        <select name="department" class="form-select">
            <option value="">All Departments</option>
            @foreach (var dept in CatalogData.Departments)
            {
                <option value="@dept.Id" selected="@(Department == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-3">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (!filteredCourses.Any())
{
    <div class="alert alert-info">No courses match your criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Code</th>
                <th>Title</th>
                <th>Department</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in filteredCourses)
            {
                var dept = CatalogData.GetDepartment(course.DepartmentId);
                <tr>
                    <td>@course.Code</td>
                    <td>@course.Title</td>
                    <td>@dept?.Name</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td><a href="/courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? Department { get; set; }

    private IEnumerable<Course> filteredCourses = [];

    protected override void OnInitialized()
    {
        filteredCourses = CatalogData.Courses;

        if (Department.HasValue)
        {
            filteredCourses = filteredCourses.Where(c => c.DepartmentId == Department.Value);
        }

        if (!string.IsNullOrWhiteSpace(Search))
        {
            var searchLower = Search.ToLowerInvariant();
            filteredCourses = filteredCourses.Where(c =>
                c.Title.Contains(searchLower, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(searchLower, StringComparison.OrdinalIgnoreCase));
        }
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Data
@using System.ComponentModel.DataAnnotations

<PageTitle>Enrollment Request — University Course Catalog</PageTitle>

<h1>Enrollment Request</h1>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
            <strong>@(CatalogData.GetCourse(Model.CourseId)?.Title ?? "the selected course")</strong>
            has been received. You will be notified by email once it is processed.</p>
    </div>
    <a href="/courses" class="btn btn-primary">Back to Catalog</a>
}
else
{
    <p>Fill out the form below to request enrollment in a course.</p>

    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" class="needs-validation">
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., STU-12345" />
            <ValidationMessage For="() => Model.StudentId" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-select">
                <option value="0">— Select a course —</option>
                @foreach (var course in CatalogData.Courses)
                {
                    <option value="@course.Id">@course.Code — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Request</button>
        <a href="/courses" class="btn btn-outline-secondary ms-2">Cancel</a>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentModel Model { get; set; } = new();

    [SupplyParameterFromQuery]
    public int? CourseId { get; set; }

    private bool submitted;

    protected override void OnInitialized()
    {
        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        submitted = true;
    }

    public class EnrollmentModel
    {
        [Required(ErrorMessage = "Name is required.")]
        public string StudentName { get; set; } = "";

        [Required(ErrorMessage = "Student ID is required.")]
        public string StudentId { get; set; } = "";

        [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
        public int CourseId { get; set; }
    }
}

